class Temperature:
    def __init__(self, celsius=0):
        self._celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("Below absolute zero!")
        self._celsius = value

    @property
    def fahrenheit(self):
        return self._celsius * 9/5 + 32

    @fahrenheit.setter
    def fahrenheit(self, value):
        self._celsius = (value - 32) * 5/9

t = Temperature(25)
print(f"Celsius: {t.celsius}")
print(f"Fahrenheit: {t.fahrenheit}")
t.fahrenheit = 100
print(f"After setting to 100F - Celsius: {t.celsius:.1f}")
t.celsius = 30
print(f"After setting to 30C - Fahrenheit: {t.fahrenheit:.1f}")

